/**
 * Right-side detail panel for a lead (Facebook lead-board style).
 * Opens when a card is clicked on the prospection board: shows the full
 * contact sheet, lets the user change the status, edit the info inline and
 * write notes without leaving the board.
 */

import { useState, useEffect, useRef } from 'react';
import toast from 'react-hot-toast';
import {
  useQuery,
  updateLead,
  // @ts-ignore -- generated by Wasp on next restart
  getLeadNotes,
  // @ts-ignore -- generated by Wasp on next restart
  addLeadNote,
  // @ts-ignore -- generated by Wasp on next restart
  deleteLeadNote,
  // @ts-ignore -- generated by Wasp on next restart
  getLeadSourceConfigs,
  // @ts-ignore -- generated by Wasp on next restart
  markLeadViewed,
  // @ts-ignore -- generated by Wasp on next restart
  getLeadCardFields,
} from 'wasp/client/operations';
import type { Lead, LeadStatusConfig } from 'wasp/entities';
import { useSmsCapability, useEmailCapability } from '../../client/capabilities';
import {
  LuX,
  LuPhone,
  LuMail,
  LuGlobe,
  LuMapPin,
  LuStar,
  LuExternalLink,
  LuPencil,
  LuSend,
  LuTrash2,
  LuUserPlus,
  LuUserCheck,
  LuClock,
  LuLoader,
  LuNotebook,
  LuMessageSquare,
  LuInfo,
  LuHistory,
} from 'react-icons/lu';
import {
  NoteThread,
  LeadEditForm,
  CopyBtn,
  formatMontrealTime,
  leadExtras,
  LeadValueText,
  LeadAvatar,
  leadStateChips,
  leadSourceColor,
  leadHistory,
  historyContacted,
  type LeadHistoryEntry,
  extraFieldId,
  isExtraFieldKey,
  visibleDetailFields,
  MAX_EXTRA_VALUE_CHARS,
  type CardFieldConfig,
  type LeadExtra,
  type LeadSourceOption,
  type LeadFormValues,
} from './leads.shared';

// ─── Read-only contact row ────────────────────────────────────────────────────

function InfoRow({
  icon,
  label,
  children,
  copyText,
}: {
  icon: React.ReactNode;
  label: string;
  children: React.ReactNode;
  copyText?: string;
}) {
  return (
    <div className='flex items-start gap-2.5 py-2.5'>
      <span className='text-muted mt-0.5 shrink-0'>{icon}</span>
      <div className='min-w-0 flex-1'>
        <div className='text-[11px] font-semibold uppercase tracking-wide text-muted'>{label}</div>
        <div className='text-[13px] leading-5 text-ink break-words'>{children}</div>
      </div>
      {copyText && <CopyBtn text={copyText} />}
    </div>
  );
}


// ─── Panel ────────────────────────────────────────────────────────────────────

/** Ce que la fiche laisse faire. L'application permet tout ; un lien de partage, ce qu'il a reçu. */
export type LeadDetailAccess = {
  status: boolean;
  edit: boolean;
  notes: boolean;
  writeNotes: boolean;
};

export const FULL_DETAIL_ACCESS: LeadDetailAccess = { status: true, edit: true, notes: true, writeNotes: true };

/**
 * La fiche elle-même, sans aucun accès aux données : tout arrive en props et
 * tout repart par des rappels.
 *
 * Deux enveloppes la nourrissent — `LeadDetailPanel` dans l'application et le
 * portail d'un lien de partage — pour que l'employé qui reçoit le lien voie
 * exactement la fiche que voit l'équipe, et non une copie qui divergerait.
 */
export function LeadDetailView({
  lead: incomingLead,
  statusConfigs,
  sources,
  cardFields: allCardFields,
  notes,
  access,
  stateChips: chipsFor,
  onClose,
  onStatus,
  onSource,
  onSaveInfo,
  onAddNote,
  onDeleteNote,
  footer,
  clearChatBubble = true,
  historyNotes,
}: {
  lead: Lead | null;
  statusConfigs: LeadStatusConfig[];
  sources: LeadSourceOption[];
  cardFields: CardFieldConfig[];
  notes: any[];
  access: LeadDetailAccess;
  /** Étiquettes d'état sous le nom (SMS, client…). */
  stateChips?: (lead: Lead) => React.ReactNode[];
  onClose: () => void;
  /** Lèvent en cas d'échec : la fiche affiche l'erreur et garde la saisie. */
  onStatus: (lead: Lead, key: string) => Promise<unknown>;
  onSource: (lead: Lead, source: string) => Promise<unknown>;
  onSaveInfo: (lead: Lead, values: LeadFormValues, extras: LeadExtra[]) => Promise<unknown>;
  onAddNote: (lead: Lead, text: string) => Promise<unknown>;
  onDeleteNote: (id: string) => Promise<unknown>;
  /** Les actions du pied de la fiche. */
  footer: (lead: Lead) => React.ReactNode;
  /** Garde de la place sous le pied pour la bulle de messagerie de l'application. */
  clearChatBubble?: boolean;
  /** Les notes d'une fiche passée, par sa clé — absent : pas de bouton « Voir les notes ». */
  historyNotes?: (identifier: string) => React.ReactNode;
}) {
  const [editing, setEditing] = useState(false);
  const [savingStatus, setSavingStatus] = useState<string | null>(null);
  const [savingSource, setSavingSource] = useState(false);
  const [noteText, setNoteText] = useState('');
  const [savingNote, setSavingNote] = useState(false);
  const [deletingNoteId, setDeletingNoteId] = useState<string | null>(null);
  const [shown, setShown] = useState(false);
  // Keeps the last lead on screen while the panel slides back out.
  const [lead, setLead] = useState<Lead | null>(incomingLead);

  // Les champs libres déclarés pour le tableau de ce prospect. La fiche ne les
  // invente pas : elle remplit ce que « Cartes » (ou la correspondance) a déclaré,
  // sinon une information saisie ici ne pourrait jamais être étoilée.
  const declaredExtras: CardFieldConfig[] = allCardFields.filter(f => isExtraFieldKey(f.key));

  const leadId = lead?.id ?? null;

  // Keep the rendered lead in sync with fresh data from the board.
  useEffect(() => {
    if (incomingLead) setLead(incomingLead);
  }, [incomingLead]);

  // Slide in when a lead is selected, slide out (then unmount) when cleared.
  useEffect(() => {
    if (incomingLead) {
      const t = window.setTimeout(() => setShown(true), 10);
      return () => window.clearTimeout(t);
    }
    setShown(false);
    const t = window.setTimeout(() => setLead(null), 200);
    return () => window.clearTimeout(t);
  }, [incomingLead?.id]);

  const [extrasDraft, setExtrasDraft] = useState<LeadExtra[]>([]);

  // Reset per-lead state when switching cards.
  useEffect(() => {
    setEditing(false);
    setNoteText('');
  }, [leadId]);

  // Escape closes the panel.
  useEffect(() => {
    if (!lead) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') onClose();
    }
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [lead, onClose]);

  const handleClose = onClose;

  if (!lead) return null;

  const l = lead as any;
  const current =
    statusConfigs.find(s => s.key === lead.status) ??
    ({ label: lead.status, color: '#9ca3af', key: lead.status } as LeadStatusConfig);
  const stateChips = chipsFor?.(lead) ?? [];

  async function handleStatus(key: string) {
    if (key === lead!.status) return;
    setSavingStatus(key);
    try {
      await onStatus(lead!, key);
    } catch (e: any) {
      toast.error(e?.message || 'Erreur lors de la mise à jour du statut');
    } finally {
      setSavingStatus(null);
    }
  }

  async function handleSource(source: string) {
    if (source === (lead as any)!.source) return;
    setSavingSource(true);
    try {
      await onSource(lead!, source);
    } catch (e: any) {
      toast.error(e?.message || 'Erreur lors de la mise à jour de la provenance');
    } finally {
      setSavingSource(false);
    }
  }

  const savedExtras = leadExtras(lead);

  /**
   * Une ligne par champ libre déclaré, garnie de la valeur du prospect s'il en a
   * une, suivie des valeurs orphelines.
   *
   * Orphelines = un champ retiré de la configuration depuis que ce prospect est
   * arrivé. Elles restent affichées et modifiables plutôt que d'être effacées au
   * premier enregistrement : le formulaire disait bien cela ce jour-là, et une
   * décision d'affichage prise après coup ne doit pas détruire la donnée.
   */
  function seedExtrasDraft(): LeadExtra[] {
    const byKey = new Map(savedExtras.map(e => [e.key, e]));
    const declared = declaredExtras.map(field => {
      const id = extraFieldId(field.key);
      const found = byKey.get(id);
      byKey.delete(id);
      return { key: id, label: field.label, value: found?.value ?? '' };
    });
    return [...declared, ...byKey.values()];
  }

  /** Les lignes à lire : les champs déclarés qui ont une valeur, puis les orphelines. */
  const visibleExtras = seedExtrasDraft().filter(e => e.value.trim().length > 0);

  /** Les champs que la fiche affiche, dans l'ordre réglé dans « Cartes ». */
  const detailFields = visibleDetailFields(allCardFields);

  /** Le rendu d'une ligne d'information, ou `null` si ce champ n'a rien à montrer. */
  function renderDetailRow(field: CardFieldConfig): React.ReactNode {
    const key = field.key;

    if (isExtraFieldKey(key)) {
      const extra = visibleExtras.find(e => e.key === extraFieldId(key));
      if (!extra) return null;
      return (
        <InfoRow key={key} icon={<LuInfo size={14} />} label={field.label} copyText={extra.value}>
          <LeadValueText value={extra.value} className='whitespace-pre-wrap' />
        </InfoRow>
      );
    }

    if (key === 'phone') {
      return (
        <InfoRow key={key} icon={<LuPhone size={14} />} label={field.label} copyText={lead!.phone ?? undefined}>
          {lead!.phone ? (
            <a href={`tel:${lead!.phone}`} className='text-accent-700 hover:underline'>
              {lead!.phone}
            </a>
          ) : (
            <span className='text-muted'>—</span>
          )}
        </InfoRow>
      );
    }

    if (key === 'email') {
      return (
        <InfoRow key={key} icon={<LuMail size={14} />} label={field.label} copyText={lead!.email ?? undefined}>
          {lead!.email ? (
            <a href={`mailto:${lead!.email}`} className='text-accent-700 hover:underline'>
              {lead!.email}
            </a>
          ) : (
            <span className='text-muted'>Non trouvé</span>
          )}
        </InfoRow>
      );
    }

    if (key === 'website') {
      return (
        <InfoRow key={key} icon={<LuGlobe size={14} />} label={field.label} copyText={lead!.website ?? undefined}>
          {lead!.website ? (
            <a
              href={lead!.website}
              target='_blank'
              rel='noopener noreferrer'
              className='text-accent-700 hover:underline'
            >
              {lead!.website.replace(/^https?:\/\//, '').replace(/\/$/, '')}
            </a>
          ) : (
            <span className='text-muted'>—</span>
          )}
        </InfoRow>
      );
    }

    if (key === 'address') {
      return (
        <InfoRow key={key} icon={<LuMapPin size={14} />} label={field.label} copyText={lead!.address ?? undefined}>
          {lead!.address ?? <span className='text-muted'>—</span>}
        </InfoRow>
      );
    }

    if (key === 'category') {
      return (
        <InfoRow key={key} icon={<LuInfo size={14} />} label={field.label} copyText={(lead as any).category ?? undefined}>
          {(lead as any).category ?? <span className='text-muted'>—</span>}
        </InfoRow>
      );
    }

    if (key === 'rating') {
      return (
        <InfoRow key={key} icon={<LuStar size={14} />} label={field.label}>
          {lead!.rating != null ? (
            <span className='flex items-center gap-1.5'>
              <span className='flex items-center gap-1'>
                <LuStar size={12} className='text-amber-400 fill-amber-400' />
                <span className='font-medium'>{Number(lead!.rating).toFixed(1)}</span>
              </span>
              {lead!.reviewCount != null && lead!.reviewCount > 0 && (
                <span className='text-muted text-xs'>{lead!.reviewCount} avis</span>
              )}
              {lead!.mapsUrl && (
                <a
                  href={lead!.mapsUrl}
                  target='_blank'
                  rel='noopener noreferrer'
                  className='text-accent-700 hover:underline text-xs flex items-center gap-0.5'
                >
                  <LuExternalLink size={11} />
                  Maps
                </a>
              )}
            </span>
          ) : (
            <span className='text-muted'>—</span>
          )}
        </InfoRow>
      );
    }

    return null;
  }

  async function handleSaveInfo(values: LeadFormValues) {
    // Les lignes vides ne sont pas enregistrées : un champ déclaré mais non
    // rempli pour ce prospect n'est pas une valeur vide, c'est une absence.
    await onSaveInfo(lead!, values, extrasDraft.filter(e => e.value.trim().length > 0));
    toast.success('Prospect mis à jour');
    setEditing(false);
  }

  async function handleAddNote(e: React.FormEvent) {
    e.preventDefault();
    if (!noteText.trim()) return;
    setSavingNote(true);
    try {
      await onAddNote(lead!, noteText);
      setNoteText('');
    } catch {
      toast.error('Erreur lors de l\'ajout');
    } finally {
      setSavingNote(false);
    }
  }

  async function handleDeleteNote(id: string) {
    setDeletingNoteId(id);
    try {
      await onDeleteNote(id);
    } catch {
      toast.error('Erreur lors de la suppression');
    } finally {
      setDeletingNoteId(null);
    }
  }

  return (
    <>
      {/* Backdrop — mobile only, so the board stays draggable on desktop. */}
      <div
        className={`fixed inset-0 bg-ink/40 z-[34] sm:hidden transition-opacity ${
          shown ? 'opacity-100' : 'opacity-0'
        }`}
        onClick={handleClose}
      />

      {/*
        The panel itself is the scroll container (header and footer stay pinned
        with `sticky`), and `overscroll-contain` keeps the wheel from reaching
        the board underneath once the panel hits its end.
      */}
      <aside
        // pb-20 : la bulle de messagerie flotte au-dessus de ce coin, rien
        // d'utile ne doit finir sous un disque de 56 px.
        className={`fixed inset-y-0 right-0 z-[35] w-full sm:w-[380px] lg:w-[420px] ${clearChatBubble ? 'pb-20' : ''} bg-white border-l border-line shadow-xl flex flex-col overflow-y-auto overscroll-contain transition-transform duration-200 ${
          shown ? 'translate-x-0' : 'translate-x-full'
        }`}
        role='dialog'
        aria-label={`Détails — ${lead.name}`}
      >
        {/* Header */}
        <div className='sticky top-0 z-10 shrink-0 bg-white px-5 py-4 border-b border-line'>
          {/* Même tête que la carte du tableau : avatar, nom, étiquettes d'état. */}
          <div className='flex items-start gap-3'>
            <LeadAvatar name={lead.name} size={44} />
            <div className='min-w-0 flex-1 pt-0.5'>
              <h2 className='text-[17px] font-semibold leading-snug text-ink break-words'>{lead.name}</h2>
              {lead.category && (
                <p className='text-[13px] text-muted capitalize'>{lead.category}</p>
              )}
              {stateChips.length > 0 && <div className='mt-1.5 flex flex-wrap gap-1.5'>{stateChips}</div>}
            </div>
            <button
              onClick={handleClose}
              className='-mr-1.5 -mt-1 flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-muted transition-colors hover:bg-canvas-200 hover:text-ink'
              aria-label='Fermer'
            >
              <LuX size={18} />
            </button>
          </div>

          {/* Status picker — les pastilles du sélecteur de colonnes du tableau. */}
          <div className='mt-4'>
            <div className='text-[11px] font-semibold uppercase tracking-wide text-muted mb-1.5'>Statut</div>
            <div className='flex flex-wrap gap-1.5'>
              {statusConfigs
                .filter(s => s.key !== 'unknown' || s.key === lead.status)
                // Sans le droit de déplacer, seule la colonne actuelle s'affiche.
                .filter(s => access.status || s.key === current.key)
                .map(s => {
                  const active = s.key === current.key;
                  return (
                    <button
                      key={s.key}
                      onClick={() => handleStatus(s.key)}
                      disabled={savingStatus !== null || !access.status}
                      aria-pressed={active}
                      className={`flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[13px] transition-colors ${access.status ? 'disabled:opacity-60' : ''} ${
                        active
                          ? 'border-ink bg-ink text-white'
                          : 'border-line bg-white text-ink-700 hover:border-ink/30'
                      }`}
                    >
                      {savingStatus === s.key ? (
                        <LuLoader size={10} className='animate-spin' />
                      ) : (
                        <span className='h-2 w-2 shrink-0 rounded-full' style={{ backgroundColor: s.color }} />
                      )}
                      {s.label}
                    </button>
                  );
                })}
            </div>
          </div>

          {/* Provenance */}
          <div className='mt-3'>
            <div className='text-[11px] font-semibold uppercase tracking-wide text-muted mb-1.5'>Provenance</div>
            <div className='flex items-center gap-2'>
              <span
                className='w-2 h-2 rounded-full shrink-0'
                style={{ backgroundColor: leadSourceColor(l.source as string, sources) }}
              />
              {access.edit ? (
                <select
                  className='input h-9 w-auto py-0 pr-8 text-[13px]'
                  value={(l.source as string) ?? 'google_maps'}
                  onChange={e => handleSource(e.target.value)}
                  disabled={savingSource}
                  title="D'où vient ce prospect"
                >
                  {sources.map(s => (
                    <option key={s.key} value={s.key}>{s.label}</option>
                  ))}
                </select>
              ) : (
                <span className='text-[13px] text-ink'>
                  {sources.find(s => s.key === ((l.source as string) ?? 'google_maps'))?.label ?? l.source ?? '—'}
                </span>
              )}
              {savingSource && <LuLoader size={12} className='animate-spin text-muted' />}
            </div>
          </div>
        </div>

        {/* Body */}
        <div className='flex-1 px-5 py-4 space-y-5'>

          {/* Contact info */}
          <section>
            <div className='flex items-center justify-between mb-1'>
              <h3 className='text-[15px] font-semibold text-ink'>Informations</h3>
              {!editing && access.edit && (
                <button
                  className='text-xs text-accent-700 hover:underline flex items-center gap-1'
                  onClick={() => {
                    setExtrasDraft(seedExtrasDraft());
                    setEditing(true);
                  }}
                >
                  <LuPencil size={11} />
                  Modifier
                </button>
              )}
            </div>

            {editing ? (
              <LeadEditForm
                initialValues={{
                  name: lead.name,
                  phone: lead.phone ?? '',
                  email: lead.email ?? '',
                  website: lead.website ?? '',
                  address: lead.address ?? '',
                  category: lead.category ?? '',
                }}
                onSave={handleSaveInfo}
                onCancel={() => setEditing(false)}
                // Un champ retiré de la fiche n'a pas non plus à s'y modifier :
                // le formulaire proposerait sinon de remplir une valeur que rien
                // n'affiche ensuite.
                hiddenKeys={allCardFields
                  .filter(f => f.onDetail === false)
                  .map(f => f.key)}
                extraFields={
                  extrasDraft.length > 0 ? (
                    <>
                      {extrasDraft.map((line, i) => (
                        <div key={`${line.key}-${i}`} className='sm:col-span-2'>
                          <label className='label'>{line.label || 'Information'}</label>
                          <textarea
                            className='input'
                            rows={2}
                            value={line.value}
                            maxLength={MAX_EXTRA_VALUE_CHARS}
                            onChange={e =>
                              setExtrasDraft(d =>
                                d.map((l, j) => (j === i ? { ...l, value: e.target.value } : l)),
                              )
                            }
                          />
                        </div>
                      ))}
                    </>
                  ) : undefined
                }
              />
            ) : (
              <div className='divide-y divide-line'>
                {/* Les lignes d'information viennent du réglage « Cartes » et non
                    d'une liste figée : sur un tableau alimenté par formulaire, la
                    note Google ne peut rien valoir et n'avait aucune raison d'occuper
                    une ligne à vide. Un champ éteint quitte la fiche sans quitter la
                    base — le téléphone continue d'armer le bouton SMS. */}
                {detailFields.map(field => renderDetailRow(field))}
                <InfoRow icon={<LuClock size={14} />} label='Ajouté le'>
                  <span className='text-muted'>{formatMontrealTime(lead.createdAt)}</span>
                  {lead.statusUpdatedAt && (
                    <span className='block text-xs text-muted'>
                      Statut modifié le {formatMontrealTime(lead.statusUpdatedAt)}
                    </span>
                  )}
                </InfoRow>
              </div>
            )}
          </section>

          {/* Historique : où cette entreprise est déjà passée. */}
          {leadHistory(lead).length > 0 && (
            <HistorySection
              entries={leadHistory(lead)}
              currentIdentifier={(lead as any).placeId ?? lead.id}
              renderNotes={historyNotes}
            />
          )}

          {/* Notes */}
          {access.notes && <section>
            <h3 className='text-[15px] font-semibold text-ink mb-3 flex items-center gap-1.5'>
              <LuNotebook size={14} className='text-muted' />
              Notes
              {(notes as any[]).length > 0 && (
                <span className='rounded-full bg-canvas-200 px-2 py-0.5 text-xs font-medium text-ink-700'>{(notes as any[]).length}</span>
              )}
            </h3>
            <NoteThread
              notes={notes as any[]}
              text={noteText}
              setText={setNoteText}
              onSubmit={handleAddNote}
              onDelete={handleDeleteNote}
              saving={savingNote}
              deletingId={deletingNoteId}
              autoFocus={false}
              scrollable={false}
              readOnly={!access.writeNotes}
            />
          </section>}
        </div>

        {/* Footer actions */}
        <div className='sticky bottom-0 z-10 shrink-0 px-5 py-3 border-t border-line bg-canvas-100 flex items-center gap-2'>
          {footer(lead)}
        </div>
      </aside>
    </>
  );
}

// ─── Dans l'application ───────────────────────────────────────────────────────

export function LeadDetailPanel({
  lead: incomingLead,
  statusConfigs,
  existingClientNames,
  onClose,
  onRefetch,
  onEmail,
  onSms,
  onConvert,
  onDelete,
}: {
  lead: Lead | null;
  statusConfigs: LeadStatusConfig[];
  existingClientNames: Set<string>;
  onClose: () => void;
  onRefetch: () => void;
  onEmail: (lead: Lead) => void;
  onSms: (lead: Lead) => void;
  onConvert: (lead: Lead) => void;
  onDelete: (lead: Lead) => void;
}) {
  const { data: sourceConfigs = [] } = useQuery(getLeadSourceConfigs);

  // Le dernier prospect ouvert, gardé pendant que la fiche se referme : ses notes
  // et ses champs restent à l'écran le temps de l'animation.
  const lastLead = useRef<Lead | null>(incomingLead);
  if (incomingLead) lastLead.current = incomingLead;
  const lead = lastLead.current;

  const boardId = (lead as any)?.searchId ?? null;
  const { data: cardFieldRows } = useQuery(
    getLeadCardFields,
    { searchId: boardId },
    { enabled: !!boardId } as any,
  );

  const identifier = (lead as any)?.placeId ?? lead?.id ?? null;
  const { data: notes = [], refetch: refetchNotes } = useQuery(
    getLeadNotes,
    { identifier },
    { enabled: !!identifier } as any,
  );

  const { canSend: smsCanSend, reason: smsReason } = useSmsCapability();
  const { canSend: emailCanSend, reason: emailReason } = useEmailCapability();

  // Ouvrir la fiche vaut « vu », et c'est ce qui annule l'alerte d'arrivée
  // (voir jobs/leadIntake) : changer le statut ne suffisait pas, on peut très
  // bien traiter un prospect sans le sortir de sa colonne.
  //
  // Piloté par `incomingLead?.id` et non par le prospect retenu : ce dernier
  // reste garni pendant les 200 ms de fermeture, et rejouerait l'appel à chaque
  // sortie.
  //
  // Le tableau n'est rechargé que si l'ouverture était la première : c'est
  // exactement quand la pastille « jamais ouvert » doit disparaître de la carte.
  // Les consultations suivantes n'écrivent rien et ne rechargent rien.
  const openedId = incomingLead?.id ?? null;
  useEffect(() => {
    if (!openedId) return;
    (markLeadViewed as any)({ leadId: openedId })
      .then((res: any) => { if (res?.marked) onRefetch(); })
      .catch(() => undefined);
  }, [openedId]);

  const notesDirty = useRef(false);

  function handleClose() {
    if (notesDirty.current) {
      notesDirty.current = false;
      onRefetch();
    }
    onClose();
  }

  return (
    <LeadDetailView
      lead={incomingLead}
      statusConfigs={statusConfigs}
      sources={sourceConfigs as LeadSourceOption[]}
      cardFields={(cardFieldRows as CardFieldConfig[]) ?? []}
      notes={notes as any[]}
      access={FULL_DETAIL_ACCESS}
      historyNotes={identifier => <PastNotes identifier={identifier} />}
      // Les notes ont leur propre section dans la fiche : pas d'étiquette en double.
      stateChips={l => leadStateChips(l, { smsCanSend, isClient: existingClientNames.has(l.name.toLowerCase()), notes: false })}
      onClose={handleClose}
      onStatus={async (l, key) => {
        await updateLead({ id: l.id, status: key });
        onRefetch();
      }}
      onSource={async (l, source) => {
        await updateLead({ id: l.id, source } as any);
        onRefetch();
      }}
      onSaveInfo={async (l, values, extras) => {
        await updateLead({
          id: l.id,
          name: values.name || undefined,
          phone: values.phone || undefined,
          email: values.email || undefined,
          website: values.website || undefined,
          address: values.address || undefined,
          category: values.category || undefined,
          extras,
        } as any);
        onRefetch();
      }}
      onAddNote={async (l, text) => {
        await addLeadNote({ leadId: l.id, text });
        notesDirty.current = true;
        refetchNotes();
      }}
      onDeleteNote={async id => {
        await deleteLeadNote({ id });
        notesDirty.current = true;
        refetchNotes();
      }}
      footer={l => (
        <AppFooter
          lead={l}
          alreadyClient={existingClientNames.has(l.name.toLowerCase())}
          smsCanSend={smsCanSend}
          smsReason={smsReason}
          emailCanSend={emailCanSend}
          emailReason={emailReason}
          onEmail={onEmail}
          onSms={onSms}
          onConvert={onConvert}
          onDelete={onDelete}
        />
      )}
    />
  );
}

function AppFooter({
  lead,
  alreadyClient,
  smsCanSend,
  smsReason,
  emailCanSend,
  emailReason,
  onEmail,
  onSms,
  onConvert,
  onDelete,
}: {
  lead: Lead;
  alreadyClient: boolean;
  smsCanSend: boolean;
  smsReason: string | null | undefined;
  emailCanSend: boolean;
  emailReason: string | null | undefined;
  onEmail: (lead: Lead) => void;
  onSms: (lead: Lead) => void;
  onConvert: (lead: Lead) => void;
  onDelete: (lead: Lead) => void;
}) {
  const l = lead as any;
  return (
    <>
      {/* Like the SMS button: the label stays put and the state shows in the
          colour — green once sent, amber while a draft is waiting. */}
      <button
        className={`gap-1.5 text-sm flex-1 justify-center ${
          !emailCanSend
            ? 'btn-secondary'
            : l.hasEmailSent
              ? 'btn-secondary text-success'
              : l.hasEmailDraft
                ? 'btn-secondary text-amber-600'
                : 'btn-primary'
        }`}
        onClick={() => onEmail(lead)}
        disabled={!lead.email || !emailCanSend}
        title={
          !emailCanSend
            ? (emailReason ?? '')
            : !lead.email
              ? 'Aucun courriel pour ce prospect'
              : l.hasEmailSent
                ? 'Déjà contacté — écrire un nouveau courriel'
                : l.hasEmailDraft
                  ? 'Brouillon en cours — cliquer pour reprendre'
                  : 'Envoyer un courriel'
        }
      >
        <LuSend size={14} />
        Courriel
      </button>
      <button
        className={`btn-secondary gap-1.5 text-sm relative ${l.hasSmsSent && smsCanSend ? 'text-success' : ''}`}
        onClick={() => onSms(lead)}
        disabled={!lead.phone || !smsCanSend}
        title={
          !smsCanSend
            ? (smsReason ?? '')
            : !lead.phone
              ? 'Aucun téléphone pour ce prospect'
              : l.smsUnreadCount
                ? `${l.smsUnreadCount} réponse(s) non lue(s)`
                : 'Envoyer un SMS'
        }
      >
        <LuMessageSquare size={14} />
        SMS
        {smsCanSend && l.smsUnreadCount > 0 && (
          <span className='ml-0.5 min-w-[16px] h-4 px-1 rounded-full bg-accent-500 text-white text-[10px] font-semibold flex items-center justify-center'>
            {l.smsUnreadCount}
          </span>
        )}
      </button>
      {lead.status === 'qualifie' &&
        (alreadyClient ? (
          <span
            className='btn-secondary gap-1.5 text-sm opacity-60 cursor-default'
            title='Déjà ajouté comme client'
          >
            <LuUserCheck size={14} />
            Client
          </span>
        ) : (
          <button
            className='btn-secondary gap-1.5 text-sm'
            onClick={() => onConvert(lead)}
            title='Créer un client depuis ce prospect'
          >
            <LuUserPlus size={14} />
            Client
          </button>
        ))}
      <button
        className='btn-danger gap-1.5 text-sm'
        onClick={() => onDelete(lead)}
        title='Supprimer ce prospect'
      >
        <LuTrash2 size={14} />
      </button>
    </>
  );
}

// ─── Historique ───────────────────────────────────────────────────────────────

const shortDate = (d: string | Date) =>
  new Date(d).toLocaleDateString('fr-CA', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'America/Toronto' });

const MATCHED_BY: Record<LeadHistoryEntry['matchedBy'], string> = {
  google: 'Reconnu par sa fiche Google',
  phone: 'Reconnu par son téléphone',
  email: 'Reconnu par son courriel',
};

/**
 * Les autres passages de la même entreprise : autres tableaux, et prospects
 * supprimés gardés dans l'archive. Ce qui répond, avant d'écrire, à « l'a-t-on
 * déjà contacté, et où en était-on ? ».
 */
function HistorySection({
  entries,
  currentIdentifier,
  renderNotes,
}: {
  entries: LeadHistoryEntry[];
  currentIdentifier: string;
  renderNotes?: (identifier: string) => React.ReactNode;
}) {
  const [open, setOpen] = useState<string | null>(null);
  const contacted = entries.some(historyContacted);
  return (
    <section aria-label='Historique'>
      <h3 className='text-[15px] font-semibold text-ink mb-1 flex items-center gap-1.5'>
        <LuHistory size={14} className='text-muted' />
        Historique
        <span className='rounded-full bg-canvas-200 px-2 py-0.5 text-xs font-medium text-ink-700'>{entries.length}</span>
      </h3>
      <p className='mb-2.5 text-[13px] text-muted'>
        {contacted
          ? 'Cette entreprise a déjà été contactée.'
          : 'Cette entreprise est déjà passée par vos tableaux.'}
      </p>
      <ul className='space-y-2'>
        {entries.map((h, i) => {
          const key = `${h.kind}:${h.identifier}:${i}`;
          const sameThread = h.identifier === currentIdentifier;
          return (
            <li key={key} className='rounded-xl border border-line bg-white px-3 py-2.5'>
              <div className='flex items-start justify-between gap-2'>
                <div className='min-w-0'>
                  <div className='text-[13px] font-medium text-ink break-words'>
                    {h.boardTitle || 'Tableau supprimé'}
                  </div>
                  <div className='text-xs text-muted'>
                    {h.kind === 'archived'
                      ? `Retiré le ${shortDate(h.archivedAt ?? h.addedAt)}${h.reason === 'board_deleted' ? ' (tableau supprimé)' : ''}`
                      : `Toujours sur ce tableau · ajouté le ${shortDate(h.addedAt)}`}
                  </div>
                </div>
                <span className='shrink-0 rounded-full border border-line px-2 py-0.5 text-xs text-ink-700'>
                  {h.statusLabel ?? h.status}
                </span>
              </div>
              <div className='mt-1.5 flex flex-wrap items-center gap-1.5'>
                {h.emails > 0 && <span className='rounded-md bg-canvas-200 px-1.5 text-[11px] leading-[18px] text-ink-700'>{h.emails} courriel{h.emails > 1 ? 's' : ''}</span>}
                {h.smsSent > 0 && <span className='rounded-md bg-canvas-200 px-1.5 text-[11px] leading-[18px] text-ink-700'>{h.smsSent} SMS envoyé{h.smsSent > 1 ? 's' : ''}</span>}
                {h.smsReplies > 0 && <span className='rounded-md bg-accent-50 px-1.5 text-[11px] leading-[18px] text-accent-800'>{h.smsReplies} réponse{h.smsReplies > 1 ? 's' : ''} SMS</span>}
                {h.notes > 0 && <span className='rounded-md bg-canvas-200 px-1.5 text-[11px] leading-[18px] text-ink-700'>{h.notes} note{h.notes > 1 ? 's' : ''}</span>}
                {!historyContacted(h) && h.notes === 0 && <span className='text-[11px] text-muted'>Jamais contacté</span>}
                <span className='text-[11px] text-muted'>· {MATCHED_BY[h.matchedBy]}</span>
              </div>
              {h.notes > 0 && (sameThread ? (
                <p className='mt-1.5 text-[11px] text-muted'>Ses notes sont dans la section Notes ci-dessous.</p>
              ) : renderNotes && (
                <>
                  <button
                    type='button'
                    className='mt-1.5 text-xs font-medium text-accent-700 hover:underline'
                    aria-expanded={open === key}
                    onClick={() => setOpen(open === key ? null : key)}
                  >
                    {open === key ? 'Masquer les notes' : 'Voir les notes'}
                  </button>
                  {open === key && <div className='mt-2'>{renderNotes(h.identifier)}</div>}
                </>
              ))}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

/** Les notes d'une fiche passée, en lecture seule. */
function PastNotes({ identifier }: { identifier: string }) {
  const { data: notes, isLoading } = useQuery(getLeadNotes, { identifier });
  if (isLoading) return <LuLoader size={14} className='animate-spin text-muted' />;
  return (
    <NoteThread
      notes={(notes as any[]) ?? []}
      text=''
      setText={() => undefined}
      onSubmit={e => e.preventDefault()}
      onDelete={() => undefined}
      saving={false}
      deletingId={null}
      autoFocus={false}
      scrollable={false}
      readOnly
    />
  );
}
